package com.bananalab.lite;
import android.app.*;import android.graphics.*;import android.widget.*;import android.text.*;
final class JavaWorkshop{
 static void show(Activity a,RuntimeWorkshop.Commands send){UiTypeface.show(new AlertDialog.Builder(a).setTitle("Java local · experimental").setItems(new String[]{"Estado de compilación","Ver fuente Java","Editar fuente Java","Preparar cambio de prueba","Compilar, probar y activar","Recuperar versión anterior","Buscar documentación del error"},(d,i)->{String[] commands={"estado java","ver java","","prepara prueba java","compila y activa java","revierte java","busca este error java"};if(i!=2){send.send(commands[i]);return;}EditText edit=new EditText(a);edit.setTextColor(Color.BLACK);edit.setBackgroundColor(Color.WHITE);edit.setTypeface(Typeface.MONOSPACE);edit.setTextSize(13);edit.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);edit.setFilters(new InputFilter[]{new InputFilter.LengthFilter(12000)});edit.setText(JavaLive.prefs(a).getString("draft",JavaLive.source(a)));final int revision=JavaLive.prefs(a).getInt("revision",0);ScrollView view=new ScrollView(a);view.addView(edit);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("BananaBehavior.java").setView(view).setNegativeButton("Cerrar",null).setPositiveButton("Guardar fuente",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{JavaLive.stage(a,edit.getText().toString(),revision);dialog.dismiss();send.send("estado java");}catch(Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);UiTypeface.show(dialog);}).setNegativeButton("Cerrar",null));}
}
